let db,recipes;const activeTags=new Set(),expanded=new Set();let saved={};try{saved=JSON.parse(appStorage.getItem('boschetto-v1')||'{}')}catch{}const selected=new Set(saved.selected||[]),checked=new Set(saved.checked||[]);
let manualItems=saved.manualItems||[];
const customRecipes=saved.customRecipes||[], recipeTags=saved.recipeTags||{}, editedRecipes=saved.editedRecipes||{};
const individual=new Set(saved.individual||[]), amounts=saved.amounts||{}, units=saved.units||{};
let weekPlan={};try{weekPlan=JSON.parse(appStorage.getItem('boschetto-calendar-v1')||'{}')}catch{}
// Migrate previous one-recipe days without losing existing assignments.
weekPlan=Object.fromEntries(Object.entries(weekPlan).map(([day,value])=>[day,(Array.isArray(value)?value:[value]).filter(Boolean).map((entry,index)=>typeof entry==='string'?{id:'legacy-'+day+'-'+index,recipeId:entry}:entry).filter(entry=>entry?.id&&entry?.recipeId)]));
function planEntries(){return Object.entries(weekPlan).flatMap(([day,entries])=>entries.map(entry=>[day,entry]))}
let shoppingState={order:[],excluded:[]};try{shoppingState={...shoppingState,...JSON.parse(appStorage.getItem('boschetto-shopping-v1')||'{}')}}catch{}
const calendarExcluded=new Set(shoppingState.excluded);
for(const key of [...calendarExcluded]){const parts=key.split('|');if(parts.length===3){const [day,...rest]=parts;for(const entry of weekPlan[day]||[])calendarExcluded.add(day+'|'+entry.id+'|'+rest.join('|'));calendarExcluded.delete(key)}}
try{appStorage.setItem('boschetto-calendar-v1',JSON.stringify(weekPlan))}catch{}
function saveShoppingState(){shoppingState.excluded=[...calendarExcluded];try{appStorage.setItem('boschetto-shopping-v1',JSON.stringify(shoppingState))}catch{}}
const itemKey=i=>i.ingredient_id+'|'+String(i.unit||'').trim();
const calendarLineKey=(day,entry,i)=>day+'|'+entry.id+'|'+itemKey(i);
function plannedIngredients(){return planEntries().flatMap(([day,entry])=>{const r=recipes.find(r=>r.recipe_id===entry.recipeId);return r?r.ingredients.map((i,index)=>({...i,quantity:amounts[lineKey(r,index)]??i.quantity,unit:ingredientUnit(r,index)})).filter(i=>!calendarExcluded.has(calendarLineKey(day,entry,i))):[]})}
let toastTimer;
function showToast(message){const toast=$('#toast');clearTimeout(toastTimer);toast.textContent=message;toast.hidden=false;if(toast.showPopover&&!toast.matches(':popover-open'))toast.showPopover();toastTimer=setTimeout(()=>{if(toast.hidePopover&&toast.matches(':popover-open'))toast.hidePopover();toast.hidden=true},1800)}
const lineKey=(r,i)=>r.recipe_id+':'+i;
const included=(r,i)=>individual.has(lineKey(r,i));
const persist=()=>{try{appStorage.setItem('boschetto-v1',JSON.stringify({selected:[...selected],checked:[...checked],individual:[...individual],amounts,units,customRecipes,manualItems,editedRecipes,recipeTags}))}catch{}};
const fmt=n=>new Intl.NumberFormat('it-IT',{maximumFractionDigits:2}).format(n);
const ingredientUnit=(r,index)=>units[lineKey(r,index)]??r.ingredients[index].unit??'';
function unitOptions(current){return [...new Set([current,'g','porzione','ml','pezzi'].filter(u=>u!==null&&u!==undefined))].map(u=>`<option value="${esc(u)}" ${u===current?'selected':''}>${esc(u||'—')}</option>`).join('')}
function quantity(q,u){return `${q??'q.b.'}${u?' '+u:''}`}
let recipeView='categories';
const categoryOpen=new Map();
function render(){const q=normalize($('#search').value),cat=$('#category').value;const list=recipes.filter(r=>(!cat||r.categories.includes(cat))&&[...activeTags].every(t=>r.tags.includes(t))&&r.search.includes(q));$('#count').textContent=`${list.length} ricette${q||cat||activeTags.size?' trovate':''}`;
 const groups=[...new Set(list.map(r=>r.category||'Senza categoria'))];
 $('#recipes').innerHTML=list.length?groups.map((category,index)=>{const rows=list.filter(r=>(r.category||'Senza categoria')===category);const open=q||cat||activeTags.size||categoryOpen.get(category)===true||(!categoryOpen.has(category)&&index===0);return `<details class="recipe-category" data-category-group="${esc(category)}" ${open?'open':''}><summary><span class="category-heading"><span class="category-chevron" aria-hidden="true">›</span>${esc(category)} <span class="category-count">${rows.length}</span></span><button type="button" class="category-new" data-new-category="${esc(category)}" aria-label="Nuova ricetta in ${esc(category)}">+ Nuova</button></summary><div class="category-recipes">${rows.map(recipeMarkup).join('')}</div></details>`}).join(''):'<div class="no-results">Nessuna ricetta trovata. Prova un altro ingrediente o azzera i filtri.</div>';
 if(recipeView==='table')$('#recipes').innerHTML=tableMarkup(list);
 $('#tags').querySelectorAll('button').forEach(b=>{b.classList.toggle('active',activeTags.has(b.dataset.tag));b.setAttribute('aria-pressed',activeTags.has(b.dataset.tag))});$('#recipes').querySelectorAll('[data-select]').forEach(b=>{const r=recipes.find(r=>r.recipe_id===b.dataset.select);const n=r.ingredients.filter((_,i)=>included(r,i)).length;b.indeterminate=n>0&&n<r.ingredients.length});renderShopping();}
function recipeMarkup(r){return `<article draggable="true" data-drag-recipe="${r.recipe_id}" class="recipe ${r.ingredients.some((_,i)=>included(r,i))?'selected':''}"><div class="recipe-head"><input type="checkbox" data-select="${esc(r.recipe_id)}" ${r.ingredients.length&&r.ingredients.every((_,i)=>included(r,i))?'checked':''} aria-label="Aggiungi ${esc(r.name)} alla spesa"><div class="recipe-info"><div class="recipe-name">${esc(r.name)}</div><div class="recipe-meta"><span class="category-label">${esc(r.category)}</span>${r.tags.map(t=>`<span class="pill">${esc(t)}</span>`).join('')}<button type="button" class="edit-tags" data-edit-tags="${r.recipe_id}" aria-label="Modifica tag di ${esc(r.name)}">+ Tag</button></div></div><button type="button" class="edit-recipe" data-edit-recipe="${r.recipe_id}" aria-label="Modifica ${esc(r.name)}">Modifica</button><button class="expand" data-expand="${r.recipe_id}" aria-label="Ingredienti di ${esc(r.name)}" aria-expanded="${expanded.has(r.recipe_id)}" aria-controls="ingredients-${r.recipe_id}">${expanded.has(r.recipe_id)?'−':'⌄'}</button></div>${expanded.has(r.recipe_id)?`<div class="ingredients" id="ingredients-${r.recipe_id}"><div class="ingredients-title"><span>INGREDIENTI</span><span>Per ${esc(r.servings||'—')} persone</span></div>${r.ingredients.map((i,index)=>`<div class="ingredient"><input type="checkbox" data-line="${lineKey(r,index)}" id="line-${lineKey(r,index)}" ${included(r,index)?'checked':''} aria-label="Aggiungi ${esc(i.ingredient_name)}"><label for="line-${lineKey(r,index)}">${esc(i.ingredient_name)} <small>· ${esc(i.name_nl)}</small></label><label class="quantity-edit"><input data-amount="${lineKey(r,index)}" aria-label="Quantità di ${esc(i.ingredient_name)}" value="${esc(amounts[lineKey(r,index)]??i.quantity??'q.b.')}"><select data-unit="${lineKey(r,index)}" aria-label="Unità di ${esc(i.ingredient_name)}">${unitOptions(ingredientUnit(r,index))}</select></label></div>`).join('')}${r.cooking_notes?`<p class="small">${esc(r.cooking_notes)}</p>`:''}</div>`:''}</article>`}
function renderShopping(){const items=new Map();const sources=recipes.flatMap(r=>r.ingredients.flatMap((original,index)=>included(r,index)?[{...original,quantity:amounts[lineKey(r,index)]??original.quantity,unit:ingredientUnit(r,index)}]:[])).concat(manualItems,plannedIngredients());sources.forEach(i=>{const unit=String(i.unit||'').trim();const key=i.ingredient_id+'|'+unit;const num=Number(String(i.quantity??'').replace(',','.'));const numeric=i.quantity!==null&&i.quantity!==''&&Number.isFinite(num);if(!items.has(key))items.set(key,{...i,key,sum:0,notes:new Set(),numeric:false});const item=items.get(key);if(numeric){item.sum+=num;item.numeric=true}else item.notes.add(i.quantity||'q.b.')});const orderedItems=[...items.values()].sort((a,b)=>{const ai=shoppingState.order.indexOf(a.key),bi=shoppingState.order.indexOf(b.key);return (ai<0?Infinity:ai)-(bi<0?Infinity:bi)||a.ingredient_name.localeCompare(b.ingredient_name,'it')});const recipeCount=recipes.filter(r=>r.ingredients.some((_,i)=>included(r,i))).length;$('#selected-count').textContent=recipeCount?`${recipeCount} ricette · ${items.size} ingredienti`:(items.size?`${items.size} ingredienti`:'Nessun ingrediente selezionato');$('#clear').disabled=!items.size;$('#copy-list').disabled=!items.size;window.shoppingText='Bar Boschetto — Lista della spesa\n'+orderedItems.map(i=>`• ${i.ingredient_name}: ${[i.numeric?quantity(fmt(i.sum),i.unit):'',...i.notes].filter(Boolean).join(' + ')}`).join('\n');$('#shopping-list').innerHTML=items.size?orderedItems.map(i=>`<div class="shop-row" draggable="true" data-shop-key="${esc(i.key)}"><span class="shop-drag" aria-hidden="true" title="Trascina per riordinare">⠿</span><span class="shop-name">${esc(i.ingredient_name)}</span><span class="qty">${esc([i.numeric?quantity(fmt(i.sum),i.unit):'',...i.notes].filter(Boolean).join(' + '))}</span><span class="shop-move"><button type="button" data-move-shop="${esc(i.key)}" data-direction="-1" aria-label="Sposta ${esc(i.ingredient_name)} su">↑</button><button type="button" data-move-shop="${esc(i.key)}" data-direction="1" aria-label="Sposta ${esc(i.ingredient_name)} giù">↓</button></span><button class="delete-item" data-remove="${esc(i.key)}" aria-label="Elimina ${esc(i.ingredient_name)} dalla lista" title="Elimina dalla lista"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/></svg></button></div>`).join(''):'<div class="empty"><div class="empty-icon">♧</div><strong>Il buono deve ancora arrivare.</strong><p>Seleziona le ricette che vuoi cucinare: gli ingredienti compariranno qui.</p></div>';}
$('#search').addEventListener('input',render);$('#category').addEventListener('change',render);$('#reset').onclick=()=>{$('#search').value='';$('#category').value='';activeTags.clear();render()};$('#tags').onclick=e=>{const b=e.target.closest('[data-tag]');if(b){activeTags.has(b.dataset.tag)?activeTags.delete(b.dataset.tag):activeTags.add(b.dataset.tag);render()}};$('#recipes').onclick=e=>{const editButton=e.target.closest('[data-edit-recipe]');if(editButton){openEditRecipe(editButton.dataset.editRecipe);return}const newButton=e.target.closest('[data-new-category]');if(newButton){e.preventDefault();openRecipeForm(newButton.dataset.newCategory);return}const tagButton=e.target.closest('[data-edit-tags]');if(tagButton){openTagEditor(tagButton.dataset.editTags);return}const b=e.target.closest('[data-expand]');if(b){expanded.has(b.dataset.expand)?expanded.delete(b.dataset.expand):expanded.add(b.dataset.expand);render()}};$('#recipes').onchange=e=>{const id=e.target.dataset.select,line=e.target.dataset.line,amount=e.target.dataset.amount,unit=e.target.dataset.unit;if(id){const r=recipes.find(r=>r.recipe_id===id);r.ingredients.forEach((_,i)=>e.target.checked?individual.add(lineKey(r,i)):individual.delete(lineKey(r,i)));selected.delete(id)}else if(line){e.target.checked?individual.add(line):individual.delete(line);if(e.target.checked)showToast('aggiunto!')}else if(unit){units[unit]=e.target.value}else if(amount){const value=e.target.value.trim(),number=Number(value.replace(',','.'));if(!value||(Number.isFinite(number)&&number<0)){e.target.setCustomValidity('Inserisci una quantità positiva o q.b.');e.target.reportValidity();return}e.target.setCustomValidity('');amounts[amount]=value}else return;persist();render()};$('#shopping-list').onclick=e=>{const move=e.target.closest('[data-move-shop]');if(move){const keys=shoppingKeys(),from=keys.indexOf(move.dataset.moveShop),to=from+Number(move.dataset.direction);if(to>=0&&to<keys.length)reorderShopping(move.dataset.moveShop,keys[to]);return}const b=e.target.closest('[data-remove]');if(!b)return;for(const [day,entry] of planEntries()){const r=recipes.find(r=>r.recipe_id===entry.recipeId);if(r)r.ingredients.forEach((i,index)=>{const item={...i,unit:ingredientUnit(r,index)};if(itemKey(item)===b.dataset.remove)calendarExcluded.add(calendarLineKey(day,entry,item))})}saveShoppingState();manualItems=manualItems.filter(i=>i.ingredient_id+'|'+String(i.unit||'').trim()!==b.dataset.remove);recipes.forEach(r=>r.ingredients.forEach((i,index)=>{if(i.ingredient_id+'|'+String(ingredientUnit(r,index)).trim()===b.dataset.remove)individual.delete(lineKey(r,index))}));persist();render()};$('#clear').onclick=()=>{selected.clear();individual.clear();checked.clear();manualItems=[];for(const [day,entry] of planEntries()){const r=recipes.find(r=>r.recipe_id===entry.recipeId);if(r)r.ingredients.forEach((i,index)=>calendarExcluded.add(calendarLineKey(day,entry,{...i,unit:ingredientUnit(r,index)})))}saveShoppingState();persist();render()};document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#search').focus()}});
try{db=await appStorage.catalog();const catalog=new Map(db.catalogo_ingredienti.map(i=>[i.ingredient_id,i]));recipes=db.ricette.map(r=>{const ingredients=db.ricette_ingredienti.filter(i=>i.recipe_id===r.recipe_id).map(i=>({...i,name_nl:catalog.get(i.ingredient_id)?.name_nl||''}));return {...r,tags:split(r.tags),categories:[r.category,...split(r.additional_categories)],ingredients,search:normalize([r.name,r.category,r.tags,...ingredients.flatMap(i=>[i.ingredient_name,i.name_nl])].join(' '))}});recipes.push(...customRecipes.map(prepareRecipe));recipes=recipes.map(r=>prepareRecipe({...r,...editedRecipes[r.recipe_id],tags:recipeTags[r.recipe_id]??editedRecipes[r.recipe_id]?.tags??r.tags}));for(const id of selected)if(!recipes.some(r=>r.recipe_id===id))selected.delete(id);for(const r of recipes)if(selected.has(r.recipe_id))r.ingredients.forEach((_,i)=>individual.add(lineKey(r,i)));selected.clear();persist();refreshFilters();render()}catch(e){$('#recipes').innerHTML='<p role="alert">Il ricettario non è disponibile. Ricarica la pagina per riprovare.</p>';console.error(e)}

$('#copy-list').onclick=async()=>{try{await navigator.clipboard.writeText(window.shoppingText);$('#copy-status').textContent='Lista copiata. Puoi incollarla anche in Google Keep.'}catch{$('#copy-fallback').hidden=false;$('#copy-fallback').value=window.shoppingText;$('#copy-fallback').focus();$('#copy-fallback').select();$('#copy-status').textContent='Premi Ctrl+C (o Copia sul telefono) per copiare la lista.'}};

function prepareRecipe(r){return {...r,categories:r.categories||[r.category],search:normalize([r.name,r.category,...r.tags,...r.ingredients.flatMap(i=>[i.ingredient_name,i.name_nl])].join(' '))}}
function refreshFilters(){
 const category=$('#category').value;
 const cats=[...new Set(recipes.flatMap(r=>r.categories).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'it'));
 $('#total').textContent=recipes.length;
 $('#category').innerHTML='<option value="">Tutte le categorie</option>'+cats.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');$('#category').value=category;
 $('#category-suggestions').innerHTML=cats.map(c=>`<option value="${esc(c)}">`).join('');
 $('#ingredient-suggestions').innerHTML=[...new Set(recipes.flatMap(r=>r.ingredients.map(i=>i.ingredient_name)))].sort().map(n=>`<option value="${esc(n)}">`).join('');
 $('#tags').innerHTML=[...new Set(recipes.flatMap(r=>r.tags))].sort().map(t=>`<button class="tag-button" data-tag="${esc(t)}" aria-pressed="false">${esc(t)}</button>`).join('');
}
function addIngredientRow(){const row=document.createElement('div');row.className='new-ingredient';row.innerHTML=`<label>Ingrediente<input name="ingredient-name" list="ingredient-suggestions" required maxlength="150" placeholder="Es. pomodori"></label><label>Quantità<input name="ingredient-quantity" required maxlength="40" value="q.b." placeholder="200 o q.b."></label><label>Unità<select name="ingredient-unit">${unitOptions('g')}</select></label><button type="button" class="delete-item" aria-label="Rimuovi riga ingrediente">×</button>`;row.querySelector('button').onclick=()=>{if($('#new-ingredients').children.length>1)row.remove()};$('#new-ingredients').append(row);return row}
let editingRecipeId=null;
function openRecipeForm(category=''){editingRecipeId=null;$('#recipe-form-title').textContent='Una nuova ricetta di casa';$('#recipe-form').reset();$('#new-category').value=category;$('#new-ingredients').innerHTML='';addIngredientRow();$('#form-error').textContent='';$('#recipe-dialog').showModal();renderTagSuggestions('#new-tag-suggestions','#new-tags');$('#new-name').focus()}
$('#new-recipe').onclick=()=>openRecipeForm();
$('#cancel-recipe').onclick=()=>$('#recipe-dialog').close();
$('#add-ingredient').onclick=()=>addIngredientRow().querySelector('input').focus();

function openEditRecipe(id){const r=recipes.find(r=>r.recipe_id===id);openRecipeForm(r.category);editingRecipeId=id;$('#recipe-form-title').textContent='Modifica ricetta';$('#new-name').value=r.name;$('#new-servings').value=r.servings||2;$('#new-tags').value=r.tags.join('; ');$('#new-notes').value=r.cooking_notes||'';$('#new-ingredients').innerHTML='';r.ingredients.forEach((i,index)=>{const row=addIngredientRow();row.dataset.originalIndex=index;row.querySelector('[name="ingredient-name"]').value=i.ingredient_name;row.querySelector('[name="ingredient-quantity"]').value=amounts[lineKey(r,index)]??i.quantity??'q.b.';row.querySelector('[name="ingredient-unit"]').innerHTML=unitOptions(ingredientUnit(r,index))});$('#new-name').focus()}
$('#recipe-form').onsubmit=e=>{
 e.preventDefault();if(!e.target.reportValidity())return;
 const id=editingRecipeId||'C'+crypto.randomUUID(),original=recipes.find(r=>r.recipe_id===id),ingredients=[],selectedLines=[];
 const catalog=new Map(db.catalogo_ingredienti.map(i=>[normalize(i.name_it),{ingredient_id:i.ingredient_id,ingredient_name:i.name_it,name_nl:i.name_nl}]));for(const i of recipes.flatMap(r=>r.ingredients))catalog.set(normalize(i.ingredient_name),i);
 for(const row of $('#new-ingredients').children){const name=row.querySelector('[name="ingredient-name"]').value.trim(),q=row.querySelector('[name="ingredient-quantity"]').value.trim(),unit=row.querySelector('[name="ingredient-unit"]').value.trim();if(!name||!q||Number(q.replace(',','.'))<0){$('#form-error').textContent='Inserisci ingredienti e quantità validi.';return}const known=catalog.get(normalize(name));const item={recipe_id:id,ingredient_id:known?.ingredient_id||'CI'+crypto.randomUUID(),ingredient_name:known?.ingredient_name||name,name_nl:known?.name_nl||'',quantity:q,unit};const oldIndex=row.dataset.originalIndex;if(original&&oldIndex!==undefined&&original.ingredients[oldIndex]?.ingredient_id===item.ingredient_id&&individual.has(lineKey(original,oldIndex)))selectedLines.push(id+':'+ingredients.length);ingredients.push(item);catalog.set(normalize(name),item)}
 const name=$('#new-name').value.trim(),category=$('#new-category').value.trim();if(!name||!category||!ingredients.length){$('#form-error').textContent='Inserisci nome, categoria e almeno un ingrediente.';return}
 const recipe={recipe_id:id,name,category,categories:[category],servings:$('#new-servings').value,tags:cleanTags($('#new-tags').value),ingredients,cooking_notes:$('#new-notes').value.trim()};
 const nextIndividual=new Set([...individual].filter(k=>!k.startsWith(id+':')).concat(selectedLines)),nextAmounts=Object.fromEntries(Object.entries(amounts).filter(([k])=>!k.startsWith(id+':'))),nextUnits=Object.fromEntries(Object.entries(units).filter(([k])=>!k.startsWith(id+':'))),nextTags={...recipeTags,[id]:recipe.tags},nextEdited={...editedRecipes},nextCustom=[...customRecipes];
 if(editingRecipeId)nextEdited[id]=recipe;else nextCustom.push(recipe);
 try{appStorage.setItem('boschetto-v1',JSON.stringify({selected:[...selected],checked:[],individual:[...nextIndividual],amounts:nextAmounts,units:nextUnits,customRecipes:nextCustom,manualItems,editedRecipes:nextEdited,recipeTags:nextTags}))}catch{$('#form-error').textContent='Salvataggio non riuscito. I dati inseriti restano nel modulo.';return}
 individual.clear();nextIndividual.forEach(k=>individual.add(k));for(const key of Object.keys(amounts))delete amounts[key];Object.assign(amounts,nextAmounts);for(const key of Object.keys(units))delete units[key];Object.assign(units,nextUnits);Object.assign(recipeTags,nextTags);Object.assign(editedRecipes,nextEdited);customRecipes.splice(0,customRecipes.length,...nextCustom);
 if(editingRecipeId)recipes=recipes.map(r=>r.recipe_id===id?prepareRecipe(recipe):r);else recipes.push(prepareRecipe(recipe));categoryOpen.set(category,true);$('#search').value='';$('#category').value='';activeTags.clear();expanded.add(id);refreshFilters();render();renderWeek();$('#recipe-dialog').close();if(editingRecipeId)showToast('modificato');$('#recipe-status').textContent=editingRecipeId?'Ricetta aggiornata nelle viste Tabella e Categorie.':'Ricetta aggiunta e salvata in questo browser.';
};

let editingTagsId=null;
function cleanTags(value){const known=new Map(recipes.flatMap(r=>r.tags).map(t=>[normalize(t),t]));const unique=new Map();for(const t of split(value)){const key=normalize(t);if(!unique.has(key))unique.set(key,known.get(key)||t)}return [...unique.values()]}
function renderTagSuggestions(target,input){const tags=[...new Set(recipes.flatMap(r=>r.tags))].sort((a,b)=>a.localeCompare(b,'it'));$(target).innerHTML=tags.map(t=>`<button type="button" class="tag-button" data-suggest-tag="${esc(t)}">${esc(t)}</button>`).join('');$(target).onclick=e=>{const b=e.target.closest('[data-suggest-tag]');if(!b)return;const tags=cleanTags($(input).value+';'+b.dataset.suggestTag);$(input).value=tags.join('; ');$(input).focus()}}
function openTagEditor(id){const recipe=recipes.find(r=>r.recipe_id===id);editingTagsId=id;$('#tag-recipe-name').textContent=recipe.name;$('#edit-recipe-tags').value=recipe.tags.join('; ');$('#tag-edit-error').textContent='';renderTagSuggestions('#edit-tag-suggestions','#edit-recipe-tags');$('#tag-dialog').showModal();$('#edit-recipe-tags').focus()}
$('#cancel-tags').onclick=()=>$('#tag-dialog').close();
$('#tag-form').onsubmit=e=>{e.preventDefault();const tags=cleanTags($('#edit-recipe-tags').value);const next={...recipeTags,[editingTagsId]:tags};try{appStorage.setItem('boschetto-v1',JSON.stringify({selected:[...selected],checked:[],individual:[...individual],amounts,units,customRecipes,manualItems,editedRecipes,recipeTags:next}))}catch{$('#tag-edit-error').textContent='Salvataggio non riuscito. I tag inseriti restano nel modulo.';return}recipeTags[editingTagsId]=tags;recipes=recipes.map(r=>r.recipe_id===editingTagsId?prepareRecipe({...r,tags}):r);const available=new Set(recipes.flatMap(r=>r.tags));for(const t of activeTags)if(!available.has(t))activeTags.delete(t);refreshFilters();render();$('#tag-dialog').close();$('#recipe-status').textContent='Tag aggiornati e salvati in questo browser.'};

$('#manual-unit').innerHTML=unitOptions('g');
$('#manual-form').onsubmit=e=>{e.preventDefault();if(!e.target.reportValidity())return;const name=$('#manual-name').value.trim(),q=$('#manual-quantity').value.trim(),unit=$('#manual-unit').value;if(!name||!q||Number(q.replace(',','.'))<0){$('#manual-error').textContent='Inserisci nome e quantità validi.';return}const known=db.catalogo_ingredienti.find(i=>normalize(i.name_it)===normalize(name)||normalize(i.name_nl)===normalize(name));const custom=recipes.flatMap(r=>r.ingredients).concat(manualItems).find(i=>normalize(i.ingredient_name)===normalize(name));const item={ingredient_id:known?.ingredient_id||custom?.ingredient_id||'MI'+crypto.randomUUID(),ingredient_name:known?.name_it||custom?.ingredient_name||name,quantity:q,unit};manualItems.push(item);try{appStorage.setItem('boschetto-v1',JSON.stringify({selected:[...selected],checked:[],individual:[...individual],amounts,units,customRecipes,manualItems,editedRecipes,recipeTags}))}catch{manualItems.pop();$('#manual-error').textContent='Salvataggio non riuscito.';return}$('#manual-name').value='';$('#manual-quantity').value='1';$('#manual-error').textContent='';renderShopping();showToast('aggiunto!');$('#manual-name').focus()};

// Each planned occurrence contributes independently to shopping totals.
const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
function monday(date){const d=new Date(date);d.setHours(12,0,0,0);d.setDate(d.getDate()-(d.getDay()+6)%7);return d}
let weekStart=monday(new Date()),pickerDate=null;
function weekDates(){return Array.from({length:7},(_,i)=>{const d=new Date(weekStart);d.setDate(d.getDate()+i);return d})}
function savePlan(next){try{appStorage.setItem('boschetto-calendar-v1',JSON.stringify(next));weekPlan=next;return true}catch{$('#calendar-status').textContent='Impossibile salvare il calendario in questo browser.';return false}}
function renderWeek(){const days=weekDates();const format=d=>d.toLocaleDateString('it-IT',{day:'numeric',month:'long'});$('#week-range').textContent=`${format(days[0])} – ${format(days[6])} ${days[6].getFullYear()}`;$('#week-days').innerHTML=days.map(d=>{const key=dateKey(d),entries=(weekPlan[key]||[]).filter(entry=>recipes?.some(r=>r.recipe_id===entry.recipeId)),label=d.toLocaleDateString('it-IT',{weekday:'long',day:'numeric',month:'long'});return `<div class="week-day ${key===dateKey(new Date())?'today':''}" data-day="${key}"><div class="day-title">${esc(d.toLocaleDateString('it-IT',{weekday:'short'}))}<span>${d.getDate()}</span></div><div class="planned-list">${entries.map(entry=>{const r=recipes.find(r=>r.recipe_id===entry.recipeId);return `<div class="planned-recipe"><strong>${esc(r.name)}</strong><button type="button" class="text-button" data-remove-day="${key}" data-remove-entry="${esc(entry.id)}" aria-label="Rimuovi ${esc(r.name)} da ${esc(label)}">Rimuovi</button></div>`}).join('')}</div><button type="button" class="empty-day ${entries.length?'add-another':''}" data-pick-day="${key}" aria-label="Aggiungi una ricetta a ${esc(label)}"><span aria-hidden="true">+</span><small>${entries.length?'Aggiungi':'Trascina qui'}</small></button></div>`}).join('')}
function assignDay(key,id){if(!weekDates().some(d=>dateKey(d)===key)||!recipes.some(r=>r.recipe_id===id))return false;const entry={id:crypto.randomUUID(),recipeId:id};if(!savePlan({...weekPlan,[key]:[...(weekPlan[key]||[]),entry]}))return false;saveShoppingState();renderWeek();renderShopping();$('#calendar-status').textContent='Ricetta aggiunta al calendario e alla spesa.';return true}
$('#recipes').addEventListener('dragstart',e=>{if(e.target.closest('input,select,button')){e.preventDefault();return}const card=e.target.closest('[data-drag-recipe]');if(card){e.dataTransfer.setData('application/x-boschetto-recipe',card.dataset.dragRecipe);e.dataTransfer.setData('text/plain',card.dataset.dragRecipe);e.dataTransfer.effectAllowed='copy'}});
$('#week-days').addEventListener('dragover',e=>{const day=e.target.closest('[data-day]');if(day){e.preventDefault();e.dataTransfer.dropEffect='copy';day.classList.add('drag-over')}});
$('#week-days').addEventListener('dragleave',e=>{const day=e.target.closest('[data-day]');if(day&&!day.contains(e.relatedTarget))day.classList.remove('drag-over')});
$('#week-days').addEventListener('drop',e=>{e.preventDefault();const day=e.target.closest('[data-day]');if(day){day.classList.remove('drag-over');assignDay(day.dataset.day,e.dataTransfer.getData('application/x-boschetto-recipe')||e.dataTransfer.getData('text/plain'))}});
function pickerOptions(){const query=normalize($('#calendar-search').value);$('#calendar-recipe').innerHTML=recipes.filter(r=>normalize(r.name).includes(query)).map(r=>`<option value="${r.recipe_id}">${esc(r.name)}</option>`).join('');$('#calendar-recipe').selectedIndex=0}
$('#week-days').onclick=e=>{const remove=e.target.closest('[data-remove-day]');if(remove){const day=remove.dataset.removeDay,entryId=remove.dataset.removeEntry,next={...weekPlan,[day]:(weekPlan[day]||[]).filter(entry=>entry.id!==entryId)};if(!next[day].length)delete next[day];if(savePlan(next)){for(const excluded of calendarExcluded)if(excluded.startsWith(day+'|'+entryId+'|'))calendarExcluded.delete(excluded);saveShoppingState();renderWeek();renderShopping();$('#calendar-status').textContent='Ricetta rimossa dal giorno e relativi ingredienti rimossi dalla spesa.'}return}const pick=e.target.closest('[data-pick-day]');if(pick){pickerDate=pick.dataset.pickDay;$('#calendar-picker-title').textContent='Ricetta per '+new Date(pickerDate+'T12:00:00').toLocaleDateString('it-IT',{weekday:'long',day:'numeric',month:'long'});$('#calendar-search').value='';$('#calendar-error').textContent='';pickerOptions();$('#calendar-picker').showModal();$('#calendar-search').focus()}};
$('#calendar-search').oninput=pickerOptions;$('#cancel-calendar').onclick=()=>$('#calendar-picker').close();$('#calendar-form').onsubmit=e=>{e.preventDefault();if(assignDay(pickerDate,$('#calendar-recipe').value))$('#calendar-picker').close();else $('#calendar-error').textContent='Scegli una ricetta e un giorno valido.'};
for(const [id,delta] of [['#previous-week',-7],['#next-week',7]])$(id).onclick=()=>{weekStart.setDate(weekStart.getDate()+delta);$('#calendar-status').textContent='';renderWeek()};$('#current-week').onclick=()=>{weekStart=monday(new Date());renderWeek()};
$('#open-shopping').onclick=()=>{$('#shopping-drawer').showModal();$('#open-shopping').setAttribute('aria-expanded','true');$('#close-shopping').focus()};$('#close-shopping').onclick=()=>$('#shopping-drawer').close();$('#shopping-drawer').addEventListener('close',()=>{$('#open-shopping').setAttribute('aria-expanded','false');$('#open-shopping').focus()});$('#shopping-drawer').addEventListener('click',e=>{if(e.target!==$('#shopping-drawer'))return;const box=e.target.getBoundingClientRect();if(e.clientX<box.left||e.clientX>box.right||e.clientY<box.top||e.clientY>box.bottom)e.target.close()});
if(recipes)renderWeek();

$('#recipes').addEventListener('toggle',e=>{if(e.target.matches?.('[data-category-group]'))categoryOpen.set(e.target.dataset.categoryGroup,e.target.open)},true);


function tableMarkup(list){return `<div class="recipe-table-wrap" tabindex="0" aria-label="Tabella ricettario, scorri orizzontalmente per tutte le colonne"><table class="recipe-table"><caption>Ricettario · campi del foglio Excel Ricette</caption><thead><tr><th scope="col">ID</th><th scope="col">Ricetta e ingredienti</th><th scope="col">Categoria</th><th scope="col">Tag</th><th scope="col">Note</th></tr></thead><tbody>${list.map(r=>`<tr><td>${esc(r.recipe_id)}</td><td>${recipeMarkup(r)}</td><td>${esc(r.category)}</td><td><div class="tags">${r.tags.map(t=>`<span class="pill">${esc(t)}</span>`).join('')}<button type="button" class="edit-tags" data-edit-tags="${r.recipe_id}" aria-label="Modifica tag di ${esc(r.name)}">+ Tag</button></div></td><td>${esc(r.cooking_notes||'—')}</td></tr>`).join('')||'<tr><td colspan="5">Nessuna ricetta trovata.</td></tr>'}</tbody></table></div>`}
function switchRecipeView(view){recipeView=view;for(const [id,name] of [['#tab-categories','categories'],['#tab-table','table']]){$(id).setAttribute('aria-selected',view===name);$(id).tabIndex=view===name?0:-1}$('#recipes').setAttribute('aria-labelledby',view==='table'?'tab-table':'tab-categories');render()}
$('#tab-categories').onclick=()=>switchRecipeView('categories');$('#tab-table').onclick=()=>switchRecipeView('table');
for(const id of ['#tab-categories','#tab-table'])$(id).addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?'categories':e.key==='End'?'table':recipeView==='table'?'categories':'table';switchRecipeView(next);$(next==='table'?'#tab-table':'#tab-categories').focus()}});

function shoppingKeys(){return [...$('#shopping-list').querySelectorAll('[data-shop-key]')].map(row=>row.dataset.shopKey)}
function reorderShopping(source,target){const keys=shoppingKeys();if(source===target||!keys.includes(source)||!keys.includes(target))return;const from=keys.indexOf(source),to=keys.indexOf(target);keys.splice(from,1);keys.splice(to,0,source);shoppingState.order=keys;saveShoppingState();renderShopping()}
let draggingShop=null;
$('#shopping-list').addEventListener('dragstart',e=>{if(e.target.closest('button')){e.preventDefault();return}const row=e.target.closest('[data-shop-key]');if(!row)return;draggingShop=row.dataset.shopKey;e.dataTransfer.setData('application/x-boschetto-shopping',draggingShop);e.dataTransfer.effectAllowed='move';row.classList.add('shop-dragging')});
$('#shopping-list').addEventListener('dragover',e=>{const row=e.target.closest('[data-shop-key]');if(draggingShop&&row){e.preventDefault();e.dataTransfer.dropEffect='move';row.classList.add('shop-drop-target')}});
$('#shopping-list').addEventListener('dragleave',e=>{const row=e.target.closest('[data-shop-key]');if(row&&!row.contains(e.relatedTarget))row.classList.remove('shop-drop-target')});
$('#shopping-list').addEventListener('drop',e=>{if(!draggingShop)return;e.preventDefault();const row=e.target.closest('[data-shop-key]');if(row)reorderShopping(draggingShop,row.dataset.shopKey);draggingShop=null});
$('#shopping-list').addEventListener('dragend',()=>{draggingShop=null;$('#shopping-list').querySelectorAll('.shop-drop-target,.shop-dragging').forEach(row=>row.classList.remove('shop-drop-target','shop-dragging'))});

const mainNav=$('.main-nav');
function updateNavigationOffsets(){document.documentElement.style.setProperty('--nav-height',mainNav.getBoundingClientRect().height+'px');document.documentElement.style.setProperty('--calendar-height',$('#calendario').getBoundingClientRect().height+'px')}
if(window.ResizeObserver){const navigationObserver=new ResizeObserver(updateNavigationOffsets);navigationObserver.observe(mainNav);navigationObserver.observe($('#calendario'))}updateNavigationOffsets();
for(const id of ['#nav-recipes','#nav-calendar'])$(id).addEventListener('click',()=>{for(const link of mainNav.querySelectorAll('a'))link.removeAttribute('aria-current');$(id).setAttribute('aria-current','location')});
